-- =====================================================================
-- Crux baseline | 00 | extensions and schemas
--
-- HAND-WRITTEN, and the only file in this directory that is. Everything
-- else here is generated by .github/workflows/snapshot-schema.yml and will
-- be overwritten; see build/schema/REGENERATE.md.
--
-- Why this file exists at all is in build/migration/README.md. The short
-- version: fifty-one of the numbered migration files carry no executable
-- SQL, so the repository could not rebuild the database from them, and
-- three separate pieces of work have now had to recover a function
-- definition from the live project because it was in no file anywhere.
-- =====================================================================

-- Supabase puts its extensions in their own schemas. A local rebuild has
-- neither those schemas nor several of the extensions, and should not fail
-- for want of pg_net. Each one is attempted and the absence is reported
-- rather than fatal, because a baseline that only loads on Supabase is not
-- a baseline you can test against.
create schema if not exists extensions;

do $do$
declare e text; s text;
begin
  for e, s in
    select * from (values
      ('pg_stat_statements','extensions'),
      ('uuid-ossp','extensions'),
      ('pgcrypto','extensions'),
      ('supabase_vault','vault'),
      ('pg_net','extensions'),
      ('fuzzystrmatch','extensions'),
      ('pg_cron','pg_catalog')) as v(e, s)
  loop
    begin
      execute format('create extension if not exists %I with schema %I', e, s);
    exception when others then
      raise notice 'extension % not available here (%), continuing', e, sqlerrm;
    end;
  end loop;
end $do$;

-- pgcrypto lives in `extensions` on Supabase, and gen_random_uuid() is
-- called unqualified by nearly every table default. A local rebuild needs
-- it on the search path or every default breaks.
do $do$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where p.proname = 'gen_random_uuid' and n.nspname in ('public','pg_catalog')) then
    create extension if not exists pgcrypto with schema public;
  end if;
end $do$;

-- The prototype's read-only views live in their own schema. No tables, so
-- the schema is all it needs.
create schema if not exists seam;

-- The enums are in 05_types.sql, which is generated. Everything above this
-- line is hand-written, because a local rebuild has neither Supabase's
-- extension schemas nor several of its extensions, and a generated file
-- cannot know that.
